import { sql, and, eq } from "drizzle-orm";
import { db } from "./index";
import { bookmarks } from "./schema";

function describe(label: string, error: unknown) {
  const err = error as {
    constructor?: { name?: string };
    code?: unknown;
    cause?: { constructor?: { name?: string }; code?: unknown };
  };
  console.log(`--- ${label} ---`);
  console.log("outer ctor :", err?.constructor?.name);
  console.log("outer code :", err?.code);
  console.log("cause ctor :", err?.cause?.constructor?.name);
  console.log("cause code :", err?.cause?.code);
}

async function main() {
  const rows = (await db.execute(sql`select id from users order by created_at limit 1`)) as unknown as {
    id: string;
  }[];
  const userId = rows[0].id;

  const startups = (await db.execute(
    sql`select id from startups order by slug limit 2`,
  )) as unknown as { id: string }[];
  const realStartupId = startups[0].id;

  await db
    .delete(bookmarks)
    .where(and(eq(bookmarks.userId, userId), eq(bookmarks.startupId, realStartupId)));

  // 1. Duplicate insert -> unique violation (23505)
  await db.insert(bookmarks).values({ userId, startupId: realStartupId });
  try {
    await db.insert(bookmarks).values({ userId, startupId: realStartupId });
  } catch (error) {
    describe("duplicate (expect 23505)", error);
  }

  // 2. Nonexistent startup -> foreign key violation (23503)
  try {
    await db
      .insert(bookmarks)
      .values({ userId, startupId: "00000000-0000-4000-8000-000000000000" });
  } catch (error) {
    describe("nonexistent startup (expect 23503)", error);
  }

  await db
    .delete(bookmarks)
    .where(and(eq(bookmarks.userId, userId), eq(bookmarks.startupId, realStartupId)));
}

main().catch((error) => {
  console.error("probe failed:", error);
  process.exit(1);
});
