```ts
/**
 * Postgres SQLSTATE for an error thrown by Drizzle.
 *
 * Drizzle wraps driver errors in a DrizzleQueryError whose own `.code` is
 * undefined — the SQLSTATE lives on `.cause`. Walk the chain so callers can
 * branch on 23505 (unique violation) / 23503 (foreign key violation) instead of
 * treating every failure alike.
 */
export function sqlStateOf(error: unknown): string | undefined {
  const seen = new Set<unknown>();
  let current: unknown = error;
  while (typeof current === "object" && current !== null && !seen.has(current)) {
    seen.add(current);
    const code = (current as { code?: unknown }).code;
    if (typeof code === "string") return code;
    current = (current as { cause?: unknown }).cause;
  }
  return undefined;
}
```

